INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1054133-coe241', 'stk-iiiii', 'COE 241', 'info', '{"desc": "تغير اسم الكورس إلى coe241\nجودة المقرر بشكل عام: ممتاز\nالمواضيع التي يغطيها المقرر:هندسة الاتصالات وتراسل البيانات واساسيات الشبكات\nالكتاب المستخدم للمقرر: جيد\nالأسئلة والأمثلة المستخدمة في المقرر: فيه مصادر كثيره عند الدكتور اشرف محمود وهو افضل من يدرس الكورس\nمدى فائدته في الناحية التطبيقية: مهم للي ناوي يتخصص في الشبكات كـ اساس او حتى للي ناوي يتخصص في الاتصالات\n\nطبعاً الماده فيها تطبيق على الرياضيات في تحويل الاشارات باستخدام الفورير سيريز … ومقدمه على الشبكات … ودراسة انواع الاتصالات وطريقة الاتصال ومقدمه عن الـ FM,PM,and AM في الاتصالات التماثليه وشرح اكثر تفصيلي للطرق المستخدمه في ارسال البيانات في الاتصالات الرقميه والاتصالات اللاسلكيه ومقدمه عن التلفزيون الرقمي يعني يتكلم عن هندسة الاتصالات بشكل عام … كورس جداً ممتع ورائع خاصة مع الدكتور اشرف محمود … الكورس يحتوي الكثير من المعلومات والمواضيع المهمه والمفيده والكورس ماهو صعب ولا سهل وسورساته متوفره وكثيره وراح تستخدم فيه الماتلاب كـ توول في الاتصالات … الكورسات القريبه له هي EE207, EE370", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-241-data-computer-communications/120817/2", "user": "IIIII", "ts": 1339420833000, "tid": 120817, "pn": 2}}', 1339420833000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1056745-coe241', 'stk-maaf4ever', 'COE 241', 'info', '{"desc": "جودة المقرر بشكل عام :\nالمقرر ممتاز و المواضيع شيقة\n\nالمواضيع التي يغطيها المقرر :\nكثير بس أهمها الوايرلس والواير وكيف تنتقل الموجات من خلالها ، بالإضافة الى طريقة انتقال البيانات من جهاز لآخر بتتكلم عن الوسط وعن الموجه المنتقلة نفسها\n\nالكتاب المستخدم للمقرر:\nصراحة ما جربت أفتحه ^_^\"\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nالأمثلة حلوة وواقعية يعني تحس انك مهندس وانت تحل سؤال أو مثال فالمادة هذي 🙂\n\nمدى فائدته في الناحية التطبيقية:\nأنا بالنسبة لي هو أفضل المواد الي أخذتها للحين من الناحية التطبيقية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-241-data-computer-communications/120817/3", "user": "maaf4ever", "ts": 1339965303000, "tid": 120817, "pn": 3}}', 1339965303000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1373045-coe241', 'stk-computist', 'COE 241', 'info', '{"desc": "جودة المقرر بشكل عام جيد جدا، يفيدك في تعلم كيف البيانات DATA ممكن نقلها من مكان إلى مكان آخر بالشكل مناسب مع المتطلبات، تتعلم كثير من الأمور ربما بشيء من التفصيل وأحيانا بشكل قشري\n\nالمواضيع التي يغطيها المقرر في البداية يتكلم عن التطور التقني الحاصل في مجال الإتصالات ونقل البيانات سواء كانت بيانات analog مثل التلفاز او digital مثل تصفح الإنترنت مثلا، ثم يتكلم عن ضرورة وضع قوانين protocols للتواصل كما هي موجودة في ما بين البشر، فمثلا إذا كنت تريد تخاطب شخص ما في بعض الخطوات العامة لذلك:\n\nالقاء التحية 2. إنتظار الرد من الشخص المقابل 3. الحديث وطرح الأفكار على الشخص المقابل 4. تحية ختامية\nhttp://skfupm.kfupm.edu.sa/vb/attachment.php?attachmentid=13507&d=1401249816\nالكتاب المستخدم للمقررجيد بس للأسف ما كان عندي وقت أقرأه كامل، فقط اطلعت على أول شابترين وبعدين سحبت عليه لأنه ياخذ مني وقت\n\nالأسئلة والأمثلة المستخدمة في المقررالأمثلة قليلة ولكن توجد اسئلة كافية، اعتمدت على سلايدات الدكتور\n\nمدى فائدته في الناحية التطبيقيةأساس مهم بالنسبة للي يركزوا على networking حيث أنه فقط يدرس تواصل جهاز مع جهاز بشكل مباشر (بدون شبكة)، يعني واير موصل بكمبيوترين\n\nاتذكر شيئين من coe202 طبعنا فكرتهم في هذا الكورس وهما XOR operation و Multiplexing\n\nإذا تريد تسرع، ممكن تاخذ coe202 + coe241 لأنهم كليا مختلفين\nأنصح بها الخطوة للي عندة دافعية الاوريا والفرشمان\n\nبس coe241 أصعب من ناحية انها تحتاج جهد في الحفظ وشيء من الفهم + عندك term report و programming assignment ، وكلاهما عليه presentation", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-241-data-computer-communications/120817/12", "user": "Computist", "ts": 1401250858000, "tid": 120817, "pn": 12}}', 1401250858000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1484132-coe241', 'stk-krooom', 'COE 241', 'info', '{"desc": "162\nجودة المقرر بشكل عام :\nالمقرر ممتاز و المواضيع شيقة ( الاتصالات و والتشفير وانوعه و كيف البيانات تنرسل)\n\nالمواضيع التي يغطيها المقرر :\nكثير بس أهمها الوايرلس والواير وكيف تنتقل الموجات من خلالها ، بالإضافة الى طريقة انتقال البيانات من جهاز لآخر بتتكلم عن الوسط وعن الموجه المنتقلة نفسها\n\nالكتاب المستخدم للمقرر:\ndata comminucation\nمش تفاعلي وعملي, يعني لو تحب تطلع زيادة ولا السلايدات تكفي\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nلازم تكون فاهم كويس ومطلع عشان تجاوب على الهوموركات\n\nمدى فائدته في الناحية التطبيقية:\nمهم للنتوركينق 344 و يعطيك فكرة عن الاتصالات بشكل عام", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-241-data-computer-communications/120817/14", "user": "Krooom", "ts": 1512204152000, "tid": 120817, "pn": 14}}', 1512204152000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1486400-coe241', 'stk-red_black', 'COE 241', 'info', '{"desc": "جودة المقرر بشكل عام:\nجيد أو جيد جداً. ربما هذه المشكلة عندي فقط لأن هذا ليس مجال اهتمامي و لكني وجدت المواضيع مبهمة نوعاً ما في البداية و كان من الصعب أن أتخيل كيفية عمل الـ “بروتوكولات” و انتقال البيانات. و التشابه بين المواضيع حين وصلنا للإشارات التناظرية (أنالوغ) و الرقمية (ديجتال) كان مربكاً لحد ما.\n\nالمواضيع التي يغطيها المقرر:\nكما يوحي اسمه، هو يغطي الاتصالات. و لمزيد من التفصيل، يبدأ بمقدمة مختصرة عن فكرة البروتوكولات ثم يدخل في موضوع انتقال البيانات و متسلسلات و تحويل فورييه. ثم يدخل في اعتلالات النقل (impairments) كالتشويش و ضعف الإشارة. ثم يبدأ جزء أظنه الأطول و هو معني بتفاصيل نقل البيانات (التناظرية أو الرقمية) عبر الإشارات (التناظرية أو الرقمية). بعدها يختم بمسائل التعامل مع الأخطاء في النقل و الحد منها إلى جانب التحكم في سير البيانات.\n\nالكتاب المستخدم للمقرر:\nجيد أو جيد جداً. يشرح الأفكار بوضوح و لكن المشكلة هي كثرة الحشو فيه و الذي يتطلب وقتاً طويلاً جداً في القراءة. غالباً ما كنت أذاكر من الشرائح و لا أرجع إلى الكتاب إلا للأسئلة.\n\nالأسئلة والأمثلة المستخدمة في المقرر: أسئلة الكتاب و الشرائح و الواجبات ككل ممتازة في إيصال الفكرة و لا أملك إلا أن أقول أنه يجب التمرس عليها لتثبيت الأفكار.\n\nمدى فائدته في الناحية التطبيقية:\nأنهيته للتو فلا أقدر على الحكم عليه من كل النواحي. لكنه بداهة لا قدر بثمن لمن يريد أن يعمل في مجال الاتصالات و الشبكات.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-241-data-computer-communications/120817/15", "user": "Red_Black", "ts": 1516410978000, "tid": 120817, "pn": 15}}', 1516410978000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ad0rs-coe241', 'stk-ad0rs', 'COE 241', 'doc', '{"docs": [{"id": "stk-dr-f98338", "n": "Dr. Ashraf S. Hasan Mahmoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE241 T141\n\nالتحضير :\nنهاية كل كلاس\nطريقة الشرح :\nمن سلايداته ويعطي بونصات للي يشارك\nيحاول يربط الماتريال بالواقع عشان تفهم\nيعني بعد مايشرح شي يجيب مثال عن stc مثلا وكيف يستخدموا الشي ذا بالواقع\nالكويزات :\nمن السلايدات ويقول ايش الماتريال اللي المفروض تركز عليه\nالمياجر:\nمن الهوموركات والسلايدات\nالفاينلات :\nنفس المياجر\nالقريد النهائي:\nA+\nالصوت:\nواضح\nإضافات :\nالدكتور ذا مايتفوت من أفضل الدكاترة اللي درست عندهم\nللأسف ماينزل غير ال coe241 ودايم ينزل مواد لفل 5 على كلامه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1440107-coe241", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ashraf-s-hasan-mahmoud/98338/5", "user": "ad0rs", "ts": 1453412095000, "tid": 98338, "pn": 5}}]}', 1453412095000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8697-coe241', 'stk-user8697', 'COE 241', 'doc', '{"docs": [{"id": "stk-dr-f98340", "n": "Dr. Hosam Rowaihy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE 241- 132\nالتحضير :\nشبه يومي وما يهتم بالتاخير البسيط\nطريقة الشرح :\nسلابدات(مرتبة جدا) ونادرا ما يستعمل السبورة لتوضيح فكرة\nالكويزات :\nمتوسطة مائلة للصعوبة\nالمياجر:\nمتوسطة\nالفاينلات :\nغالبا زي الميجر ( لسا ما اختبرنا)\nالقريد النهائي:\nالصوت:\nواضح\nإضافات :\nيطلب term paper + programmig assignment وعليهم مع بعض 20%", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1362656-coe241", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-hosam-rowaihy/98340/3", "user": "user8697", "ts": 1399538626000, "tid": 98340, "pn": 3}}]}', 1399538626000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
